import { Link } from "react-router-dom";
import "../Styles/Home.css";

const Home = () => {
  return (
    <div className="hero-section">
      <h1>
        Unlock Your Potential.{" "}
        <span>
          Power <br></br> UTAS Businesses.
        </span>
      </h1>
      <p>
        Connect ambitious students with Dhofar companies and ministries for
        flexible, part-time work. Training options are available for newcomers.
      </p>
      <Link to="/studentlogin">
        <button className="get-start-btn">Get Start</button>
      </Link>
    </div>
  );
};

export default Home;
